s32 draw_health_hud_panel(Hud *hud_element) {
    s32  x;
    s32  y;
    s32  cnt;
    f32  ratio_x;
    f32  ratio_y;
    s32  alpha;
    s32  panel_alpha;
    s16 *p;
    s32  sel;
    Pt  *tab;
    s32  mode;
    s32  first_panel_half_width;
    s32  second_panel_half_width;
    s32  x0;
    s32  yy;
    s32  panel_cap_frame_index;
    s32  panel_middle_frame_index;
    s32  i;
    s32  health_icon_frame_index;
    Pt  *e;
    u8  *visibility_counters;

    if (hero.vehicle_mode == 2)
        goto out;
    if (hero.state.current == 0x32)
        goto out;
    x = hud_element->x;
    if (pal_mode != 0)
        y = health_hud_base_y_offset + 10;
    else
        y = health_hud_base_y_offset + 0x12;
    cnt = hud_element->cnt;
    visibility_counters = hud_element->ab;
    if (visibility_counters[0] == 0)
        goto out;
    ratio_x = convert_integer_to_float(visibility_counters[0]) /
              convert_integer_to_float(D_L00_0015F7F0_gp);
    if (1.0f < ratio_x)
        ratio_x = 1.0f;
    else if (ratio_x < 0.0f)
        ratio_x = 0.0f;
    ratio_y = convert_integer_to_float(visibility_counters[1]) /
              convert_integer_to_float(D_L00_0015F7F0_gp);
    if (1.0f < ratio_y)
        ratio_y = 1.0f;
    else if (ratio_y < 0.0f)
        ratio_y = 0.0f;
    alpha = truncate_float_to_s32(ratio_y * 128.0f);
    panel_alpha = truncate_float_to_s32((f32)health_hud_panel_max_alpha * ratio_x);
    p = hud_element->p;
    sel = p[0] >> 1;
    mode = hero_max_health;
    if (cnt == 0)
        sel = 0x1E;
    if (hero.vehicle_mode == 1)
        mode = hero.health.vehicle_mode_hp;
    if (mode == 8) {
        tab = l00_health_hud_eight_capacity_icon_offsets;
        first_panel_half_width = truncate_float_to_s32(ratio_x * 48.0f);
        second_panel_half_width = truncate_float_to_s32(ratio_x * 48.0f);
    } else if (mode == 5) {
        tab = l00_health_hud_five_capacity_icon_offsets;
        first_panel_half_width = truncate_float_to_s32(ratio_x * 32.0f);
        second_panel_half_width = truncate_float_to_s32(ratio_x * 16.0f);
    } else {
        second_panel_half_width = 0;
        tab = (Pt *)health_hud_default_icon_offsets;
        first_panel_half_width = truncate_float_to_s32(ratio_x * 48.0f);
    }
    yy = y + health_hud_panel_y_offset;
    panel_cap_frame_index = get_icon_frame(0x7580, 1);
    panel_middle_frame_index = get_icon_frame(0x7580, 0);
    draw_hud_sprite_flipped(panel_cap_frame_index,
                            x + first_panel_half_width,
                            yy,
                            health_hud_panel_cap_size,
                            health_hud_panel_cap_size,
                            panel_alpha);
    draw_hud_sprite(panel_middle_frame_index,
                    x - first_panel_half_width,
                    yy,
                    first_panel_half_width * 2,
                    health_hud_panel_cap_size,
                    panel_alpha);
    draw_hud_sprite(panel_cap_frame_index,
                    x - first_panel_half_width - health_hud_panel_cap_size,
                    yy,
                    health_hud_panel_cap_size,
                    health_hud_panel_cap_size,
                    panel_alpha);
    if (second_panel_half_width != 0) {
        yy += health_hud_panel_row_y_step;
        draw_hud_sprite_flipped(panel_cap_frame_index,
                                x + second_panel_half_width,
                                yy,
                                health_hud_panel_cap_size,
                                health_hud_panel_cap_size,
                                panel_alpha);
        x0 = x - second_panel_half_width;
        draw_hud_sprite(panel_middle_frame_index,
                        x0,
                        yy,
                        second_panel_half_width * 2,
                        health_hud_panel_cap_size,
                        panel_alpha);
        draw_hud_sprite(panel_cap_frame_index,
                        x0 - health_hud_panel_cap_size,
                        yy,
                        health_hud_panel_cap_size,
                        health_hud_panel_cap_size,
                        panel_alpha);
    }
    for (i = 0; i < mode; i++) {
        health_icon_frame_index = get_icon_frame(0x7536, sel);
        hud_frame(hud_element, health_icon_frame_index, x + tab[i].x, y + tab[i].y, 1, alpha);
        if (sel != 0x1E) {
            health_icon_frame_index = get_icon_frame(0x7536, 0x1E);
            hud_frame(hud_element, health_icon_frame_index, x + tab[i].x, y + tab[i].y, 1, alpha);
            health_icon_frame_index = get_icon_frame(0x7536, 0x1F);
            draw_hud_sprite(health_icon_frame_index,
                            x + tab[i].x + 0xE,
                            y + tab[i].y - 0x11,
                            0x22,
                            0x22,
                            truncate_float_to_s32((f32)(p[1] >> 4) * ratio_y));
            if (cnt == i + 1)
                sel = 0x1E;
            else
                sel = (sel + 6) % 30;
        }
    }
out:
    return hud_element->ret;
}

